    30      xmlDocPtr newDoc;
    31      xmlSAXHandlerPtr oldsax = NULL;
    32      xmlNodePtr content, newRoot;
    33      int size;
    34      int ret = 0;
    35
    36      if (depth > 40) {
    37          return(XML_ERR_ENTITY_LOOP);
    38      }
    39
    40
    41      if (lst != NULL)
    42          *lst = NULL;
    43      if (string == NULL)
    44          return(-1);
